"""Freeze the actual protocol after real smoke, before formal model outputs."""
import shutil
import time
from common import ROOT,read,write,current

assert not (ROOT/'configs/freeze.json').exists(),'Frozen protocol is immutable'
for path in ['calibration/calibration.json','calibration/probe_calibration.json','calibration/extended/results.json','calibration/final_smoke_checks.json','calibration/policy_tests.json']:
    assert read(ROOT/path)['passed'],path
assert not list((ROOT/'tasks').glob('task*/common_diagnosis/session.json'))
snapshot=ROOT/'code_snapshots/formal_frozen';snapshot.mkdir(parents=True)
for path in ROOT.glob('*.py'):shutil.copy2(path,snapshot/path.name)
shutil.copytree(ROOT/'backend',snapshot/'backend',ignore=shutil.ignore_patterns('__pycache__','*.pyc'))
shutil.copy2(ROOT/'config.json',snapshot/'config.json')
write(ROOT/'configs/freeze.json',{'version':'V2.3_formal_1','frozen_before_formal_model_outputs':True,'time':time.time(),'source_parent_commit':'0e1731fc3876202d350cf18d595679c77cc41a4f',
   'formal_tasks':10,'methods':['fixed','structured','active'],'proposals_per_arm':1,'max_probes_per_arm':2,'max_cli_sessions':180,'max_render_frames':600,'ledger_at_freeze':current(),
   'forecast':{'new_formal_common_diagnosis':10,'new_formal_repairs':30,'new_formal_CLI':40,'formal_render_max':120,'all_round_CLI_expected':49},
   'no_automatic_M_descendant':True,'H_scope':'Actual SceneAct compiler subset and reusable support/edit interfaces, not end-to-end natural image H',
   'data_exposure':'Engineered controlled exploratory tasks; template/fault-family knowledge used in calibration and smoke. Formal source configuration differs by predeclared dimensions/lens/placement; not new natural-image blind data.',
   'evaluation':'All nine fixed source and independent-transfer gates required. Any missing/failed required gate cannot pass. Primary effective repair = all source and transfer gates. Transfer repair = transfer all gates. Raw missing scores null; failed end-to-end utility separately zero.',
   'model_api':'Only logged-in Codex CLI, requested gpt-6-astra medium for formal diagnosis and coding; gpt-6.1-sol medium real attachment connectivity tested. No reconstruction LLM needed for deterministic synthetic SceneAct plans.',
   'hypothesis_limitation':'Visible full program can make root defect obvious. Smoke showed identical competing predictions and active abstention. No claim that formal tasks guarantee ambiguity or downstream advantage; no extra tasks/rounds based on winner.',
   'failure_policy':'No automatic call retries; service/build/invalid candidates retained. An interrupted call is not resampled; completed raw outputs can be evaluated without new model calls.',
   'selection':'No best-of selection, no multigeneration RSI. One patch per arm; full results including failure are kept.'})
(ROOT/'protocol.md').write_text('''# Scene-RSI V2.3 冻结协议\n\n本协议在两例真实烟测、确定性校准之后、十个正式任务的模型输出之前冻结。开发期间的修改不是预注册研究假设；正式阶段使用本协议，完整修改记录见 configs/pre_freeze_adjustments.json。父提交 0e1731fc3876202d350cf18d595679c77cc41a4f。\n\n## 范围与共同起点\n\n只比较 Fixed / Structured / Active 三种领域诊断机制，不运行 SceneEvolve、Hyperagents、多代 RSI 或自动 M 演化。每任务三组从相同 H0.py 出发：实际 SceneAct blender_scene.py 编译器，附小型可见性、支撑、材质编辑接口。源码来自 V2.2 backend/sceneact；保留 LICENSE 与归属。本轮修的是共享编译/编辑子程序，不将结果冒充自然图像到全场景重建 H 的收益。\n\n十个注入配置覆盖五类故障、两种参数化家具模板；不是十个来自独立真实房间的数据点。task01..task10 与注入类型按预定 [4,1,8,2,6,0,9,5,7,3] 排列；编号不编码故障答案。两例 smoke 不进正式表；正式配置预先统一改变宽度+0.31、焦距+5、位置x-0.4及peer位置，与 smoke 图片/配置不同，但故障家族和模板曾用于开发，明确为 controlled exploratory。transfer 使用另一模板、不同尺寸/相机/非均匀缩放/旋转/命名与部件组合。\n\n## 信息、模型与公平性\n\n每个任务一次全新 gpt-6-astra / medium 会话读取真实参考图和当前渲染、当前共享源码与公共计划、对象清单、结构和局部编辑证据，形成共同初始诊断、竞争解释及所有工具预测。完整原始反馈完全相同，实际共同调用只计一次，按1/3分摊展示。对象 Top-1 因此相同，不声称 Active 定位本身优于对照。gpt-6.1-sol / medium 用于一次真实附件联通，合成场景计划不需要额外重建模型。请求与CLI可确认返回模型分记；无法确认 actual_model=unknown。\n\nM.plan_probes(context) 读取明确预算2/已执行0与菜单。Fixed 按旧相机+尺度启发式固定 camera_calibration、geometry_replay；Structured 不主动实验；Active 按竞争解释对同一标量预测区间不相交的成对比例排序，选前两项。并列按固定菜单顺序；无预测分歧则不执行，不能制造信息。各组上限相同，实际次数单列；Fixed/Active 实际两次匹配子集另报，不把上限匹配等同实际匹配。\n\n每次实验前写不可覆盖的 stage1.json；在临时重建/场景副本执行指定对象操作，不覆盖原 .blend。实际观测回传可执行 M.plan_patch；区间外为contradicted、区间内为supported，无观测为unresolved。唯一存活假设可作为模块判断；无实验结果时仅保留初始置信>=0.7的诊断，否则unresolved。若多解释存活或全部矛盾，保存未决，不以画面Q变好推断原因。\n\n三组分别全新 gpt-6-astra / medium 编码会话，同一个提示模板、同一完整源码、同一权限和一次程序修改机会。可以修改所有模块，不受错误诊断限制。不给正确原程序、注入补丁、隐藏真值、独立评价脚本或逐函数正确实现说明；没有工具/网络/隐藏subagent/共享会话。生成与诊断模型权限均冻结为只读，附件经真实--image传入隔离暂存输入。\n\n## 探测菜单与预算\n\n七项：camera_calibration、geometry_replay、position_replay、visibility_isolation、support_relation、dependency_move、material_dependency。每项的确切标量及扰动定义由 experiment.TOOL_MEANING / fixtures.run_probe 冻结。前几项通过公共输入变化重新运行当前 H，可检验上游模块输入响应；不是只对同一个终态渲染作无识别力扰动。相机/整计划replay可object=unknown；对象操作明确记录M给出的真实对象ID，不按最大Mesh或名称第一名猜测。缺失/不适用outcome=null。支撑为归一化AABB近似；材质/依赖测试直接执行当前H。\n\n总 CLI 上限180，渲染帧上限600，包括 smoke、校准、失败与归档前任何实际工作。烟测9 CLI，正式预计10共同诊断+30编码=40；总预计49 CLI。正式最多20创建帧+40探测+60源/迁移评价=120帧，校准/烟测成本均计入总账。每调用超时沿用proposer600s、Blender600s；无自动重试，无多次采样救某一组。三组顺序按任务轮换fixed/structured/active，优先形成配对。CPU单重任务2线程，Cycles16samples/256x192/seed42/AgX，不使用GPU；设备与耗时单列。\n\n## 固定评价与统计\n\n每个候选独立检查source及另一模板transfer。九项必要功能：camera(含pose/shift)、geometry、transforms、coverage、parenting、visibility、material、mesh_integrity、surface_integrity。均required=True；必需无结果不通过。材质复制名称忽略但节点/参数保留，Mesh比较实际局部顶点/面；依赖/材质操作为机械式能力测试，未评价文字编辑。无自然图像几何真值或完整碰撞真值。\n\n主指标 Effective Shared Repair Rate：source与transfer的固定必要检查全部通过。Transfer Repair Rate：仅transfer全部通过。Regression Rate：相较同一H0原本通过的检查被修复破坏；执行失败另列，不强行称服务失败为算法回归。所有预定任务分母保留。原始缺测PSNR/SSIM等为null，失败效用可独立为零。PSNR/SSIM仅辅助，LPIPS/DINO未运行为null。\n\n模块truth/exact/related集合、对象接受范围在构造器与 configs/truth_evaluator_only.json 中在正式模型输出前确定。全局emit错误接受其实际受影响对象与父组，支撑/材质按预定作用域；不事后按模型输出改名单。对象N/A相机任务剔出对象分母；unresolved仍计入覆盖率分母。预测一致性是区间命中数/实际可测预测数；有效假设区分必须既有真实排除又最终精确模块正确。报告已决定准确率、错误已定判断、无效/无法执行/不能区分探测，以及修改函数区域数量与真实diff。\n\n不选优、不挑图，不按结果增加任务或调用。固定按task顺序全联系表；案例首个Active有效修复与首个Active失败，若无修复失败，展示首个诊断未决/错误并明确不是修复失败。统计点是故障配置/方法，重复视角不是样本；两模板不足以推出一般显著性。代码可读导致编码器直接修复的天花板风险已在正式运行前公开，不把更丰富文本或零信息探测当下游研发优势。\n\n## 隔离与交付\n\n隐藏参考正确源码、注入标签、transfer真值只在外部构造器/评价器。CLI暂存仅相应图片和提示，禁用模型文件/外部工具；所有会话新建，保存prompt/request/events/stderr/exit/time/usage。最终结果不回流后续候选（没有后续候选），不自动优化M。各代源码与diff保留，V2.2不动。\n\n本轮M由研究工程实现；不能称自动后代、跨代元能力提升或优于Hyperagents。只有后续真正不同陌生H起点与独立任务冻结M回放才可研究元提升，本轮不启动。Git代码、原始表和图公开；大日志/所有.blend按方法Release分包，无内容哈希验证。\n''')
print('Formal protocol frozen',current())
